/**
 * The SocialAPI client: one property per platform, one method per endpoint.
 *
 * ```ts
 * const client = new SocialAPI({ apiKey: process.env.SOCIALAPI_API_KEY });
 * const { data } = await client.tiktok.profile({ handle: "nike" });
 * ```
 *
 * A refusal (`404`, `403`, `402`, `429`…) throws a `SocialAPIError` with its `status`
 * and `code`. Refusals cost no credits.
 */
export class SocialAPI {
  /** Bluesky. */
  readonly bluesky: BlueskyEndpoints;
  /** Douyin. */
  readonly douyin: DouyinEndpoints;
  /** Facebook. */
  readonly facebook: FacebookEndpoints;
  /** Instagram. */
  readonly instagram: InstagramEndpoints;
  /** Kick. */
  readonly kick: KickEndpoints;
  /** LinkedIn. */
  readonly linkedin: LinkedInEndpoints;
  /** Pinterest. */
  readonly pinterest: PinterestEndpoints;
  /** Reddit. */
  readonly reddit: RedditEndpoints;
  /** Telegram. */
  readonly telegram: TelegramEndpoints;
  /** Threads. */
  readonly threads: ThreadsEndpoints;
  /** TikTok. */
  readonly tiktok: TikTokEndpoints;
  /** Twitch. */
  readonly twitch: TwitchEndpoints;
  /** X. */
  readonly x: XEndpoints;
  /** YouTube. */
  readonly youtube: YouTubeEndpoints;
  /** Your workspace: its credits. */
  readonly account: AccountEndpoints;

  constructor(options: SocialAPIOptions = {}) {
    const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env;
    const apiKey = options.apiKey ?? env?.SOCIALAPI_API_KEY;
    if (!apiKey) {
      throw new Error("Pass your API key as `new SocialAPI({ apiKey })`, or set SOCIALAPI_API_KEY.");
    }
    const configuration = new Configuration({
      basePath: (options.baseUrl ?? "https://api.socialapi.sh").replace(/\/+$/, ""),
      accessToken: apiKey,
      fetchApi: options.fetch,
      headers: options.headers,
    });
    this.bluesky = new BlueskyEndpoints(new BlueskyApi(configuration));
    this.douyin = new DouyinEndpoints(new DouyinApi(configuration));
    this.facebook = new FacebookEndpoints(new FacebookApi(configuration));
    this.instagram = new InstagramEndpoints(new InstagramApi(configuration));
    this.kick = new KickEndpoints(new KickApi(configuration));
    this.linkedin = new LinkedInEndpoints(new LinkedInApi(configuration));
    this.pinterest = new PinterestEndpoints(new PinterestApi(configuration));
    this.reddit = new RedditEndpoints(new RedditApi(configuration));
    this.telegram = new TelegramEndpoints(new TelegramApi(configuration));
    this.threads = new ThreadsEndpoints(new ThreadsApi(configuration));
    this.tiktok = new TikTokEndpoints(new TikTokApi(configuration));
    this.twitch = new TwitchEndpoints(new TwitchApi(configuration));
    this.x = new XEndpoints(new XApi(configuration));
    this.youtube = new YouTubeEndpoints(new YouTubeApi(configuration));
    this.account = new AccountEndpoints(new AccountApi(configuration));
  }
}
